// Generated by `pa add cobe --brand …`. Re-run it after your brand changes.
// cobe's own colour props, set from your brand. Every other prop is cobe's.
import createGlobe from 'cobe';

/* brand:start */
export const brandGlobe = {};
/* brand:end */

/**
 * Create a globe on `canvas` in your brand and keep it spinning.
 * cobe 2 has no render loop of its own: this one calls globe.update({ phi }) every frame.
 * Pass any cobe option (markers, arcs, theta, scale…) in `options`; `speed` is radians per frame (0 = still).
 * Returns { globe, stop }.
 */
export function spinGlobe(canvas, { theme = 'light', speed = 0.004, phi = 0, ...options } = {}) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = canvas.offsetWidth * dpr;
  const globe = createGlobe(canvas, {
    devicePixelRatio: dpr, width, height: width, phi, theta: 0.2,
    mapSamples: 16000, markerElevation: 0.01, arcWidth: 0.5, arcHeight: 0.25,
    ...brandGlobe[theme], ...options,
  });
  let raf = 0;
  const frame = () => { phi += speed; globe.update({ phi }); raf = requestAnimationFrame(frame); };
  raf = requestAnimationFrame(frame);
  return { globe, stop: () => { cancelAnimationFrame(raf); globe.destroy(); } };
}
